    return float(np.log1p(v))

def feature(s):
    s = s or {}
    comp = s.get('composition') or {}
    props = s.get('element_properties') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    total = 0.0
    weight = 0.0
    for el, x in comp.items():
        if x is None or x <= 0:
            continue
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is None or r <= 0:
            r = 1.3
        total += x * r ** 3
        weight += x
    return float(4.188790204786391 * total / (v * weight)) if weight > 0 else 0.0

