    radii = [r if r is not None and r > 0 else 1.3 for r in radii]
    best = 1000000.0
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if 0 <= i < len(sites) and 0 <= j < len(sites):
            best = min(best, d / (radii[i] + radii[j]))
    return float(best) if best < 1000000.0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    radii = [r if r is not None and r > 0 else 1.3 for r in radii]
    near = [1000000.0 for t in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i')
        j = b.get('j')
        d = b.get('distance_A')
        if i is None or j is None or d is None or d <= 0:
            continue
        if 0 <= i < n and 0 <= j < n:
            near[i] = min(near[i], d / (radii[i] + radii[j]))
    total = 0.0
    weight = 0.0
    for i in range(n):
        o = sites[i].get('occupancy')
        o = 1.0 if o is None else max(0.0, o)
        if near[i] < 1000000.0:
            total += o * near[i]
            weight += o
    return float(total / weight) if weight > 0 else 0.0

