def feature(s):
    s = s or {}
    lattice = s.get('lattice') or {}
    lengths = lattice.get('lengths_A')
    if lengths is None:
        lengths = [lattice.get('a_A'), lattice.get('b_A'), lattice.get('c_A')]
    values = [v for v in lengths if v is not None and v > 0]
    if len(values) != 3:
        return 0.0
    return float(np.log(max(values) / min(values)))

